#!/usr/bin/env node

import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'fs';
import { join } from 'path';

const inputFile =
  process.argv[2] || join(process.cwd(), 'contracts', 'openapi.bundled.json');
const generatedDir =
  process.argv[3] || join(process.cwd(), 'shared', 'api', 'generated');

const pathsDir = join(generatedDir, 'paths');
const unwrapsDir = join(generatedDir, 'unwraps');

const AUTO_HEADER = `// ============================================================
// ⚡ AUTOGENERATED by scripts/gen-api-paths.mjs
// ⚠️ DO NOT EDIT MANUALLY
// ============================================================

`;

console.log(`→ Читаем OpenAPI из: ${inputFile}`);

try {
  readFileSync(inputFile, 'utf8');
} catch {
  console.error(`❌ Ошибка: файл ${inputFile} не найден`);
  process.exit(1);
}

const doc = JSON.parse(readFileSync(inputFile, 'utf8'));
const paths = doc.paths || {};

function toIdent(s) {
  return (
    s
      .replace(/^\//, '')
      .replace(/[/{}\-]/g, '_')
      .replace(/[^a-zA-Z0-9_]/g, '')
      .replace(/__+/g, '_') || 'root'
  );
}

function cleanTag(tag) {
  return tag.replace(/[^a-zA-Z0-9_]/g, '_');
}

function extractPathParams(path) {
  return [...path.matchAll(/\{(.+?)\}/g)].map((m) => m[1]);
}

function pathToTemplate(path) {
  return path.replace(/\{(.+?)\}/g, '${params.$1}');
}

function createPathFunction(path, params) {
  if (params.length === 0) {
    return `'${path}'`;
  }

  const paramTypes = params.map((p) => `${p}: string | number`).join(', ');
  return `(params: { ${paramTypes} }) => \`${pathToTemplate(path)}\``;
}

function getResponseDataType(operation) {
  const responses = operation.responses || {};
  const successResponse =
    responses['200'] || responses['201'] || responses['204'];

  if (!successResponse) return 'unknown';

  const jsonContent = successResponse.content?.['application/json'];
  if (!jsonContent?.schema) return 'unknown';

  const schema = jsonContent.schema;

  if (schema.$ref) {
    return schema.$ref.split('/').pop();
  }

  if (schema.type === 'array' && schema.items?.$ref) {
    return `${schema.items.$ref.split('/').pop()}[]`;
  }

  if (schema.properties?.data) {
    const dataSchema = schema.properties.data;
    if (dataSchema.$ref) {
      return dataSchema.$ref.split('/').pop();
    }
    if (dataSchema.type === 'array' && dataSchema.items?.$ref) {
      return `${dataSchema.items.$ref.split('/').pop()}[]`;
    }
  }

  return 'unknown';
}

function generateUnwrapper(operation, opId) {
  const dataType = getResponseDataType(operation);
  const hasPagination =
    operation.responses?.['200']?.content?.['application/json']?.schema
      ?.properties?.page;

  if (dataType === 'unknown') {
    return `  ${opId}: (response: any) => {
    throwIfApiError(response);
    return response?.data;
  },`;
  }

  if (hasPagination) {
    return `  ${opId}: (response: any) => {
    throwIfApiError(response);
    return {
      items: response?.data ?? [],
      page: response?.page ?? null,
    };
  },`;
  }

  return `  ${opId}: (response: any) => {
    throwIfApiError(response);
    return response?.data as ${dataType};
  },`;
}

/** @type {Record<string, Array<{ opId: string; method: string; path: string; pathParams: string[]; summary: string }>>} */
const grouped = {};
/** @type {Record<string, Record<string, string>>} */
const unwrappersByTag = {};

for (const [path, methods] of Object.entries(paths)) {
  for (const [method, operation] of Object.entries(methods)) {
    if (!operation || typeof operation !== 'object') continue;

    const tag = operation.tags?.[0] || 'misc';
    const opId = operation.operationId || `${method}_${toIdent(path)}`;
    const pathParams = extractPathParams(path);

    if (!grouped[tag]) grouped[tag] = [];
    grouped[tag].push({
      opId,
      method,
      path,
      pathParams,
      summary: operation.summary || '',
    });

    if (!unwrappersByTag[tag]) unwrappersByTag[tag] = {};
    unwrappersByTag[tag][opId] = generateUnwrapper(operation, opId);
  }
}

rmSync(pathsDir, { recursive: true, force: true });
rmSync(unwrapsDir, { recursive: true, force: true });
mkdirSync(pathsDir, { recursive: true });
mkdirSync(unwrapsDir, { recursive: true });

const tagEntries = Object.entries(grouped).sort(([a], [b]) =>
  a.localeCompare(b),
);

// --- paths per tag ---
const pathModuleNames = [];

for (const [tag, items] of tagEntries) {
  const moduleName = cleanTag(tag);
  const exportName = `${moduleName}Paths`;
  pathModuleNames.push({ tag, moduleName, exportName });

  let file = AUTO_HEADER;
  file += `/** ${tag} endpoints */\n`;
  file += `export const ${exportName} = {\n`;

  for (const item of items) {
    if (item.summary) {
      file += `  /** ${item.summary} */\n`;
    }
    file += `  ${item.opId}: ${createPathFunction(item.path, item.pathParams)},\n`;
  }

  file += `} as const;\n`;
  writeFileSync(join(pathsDir, `${moduleName}.paths.ts`), file, 'utf8');
}

// PathParams + index
let pathParamsOut = `export type PathParams = {\n`;
for (const [, items] of tagEntries) {
  for (const item of items) {
    if (item.pathParams.length > 0) {
      const params = item.pathParams
        .map((p) => `    ${p}: string | number;`)
        .join('\n');
      pathParamsOut += `  ${item.opId}: {\n${params}\n  };\n`;
    }
  }
}
pathParamsOut += `};\n`;

writeFileSync(
  join(pathsDir, 'path-params.ts'),
  `${AUTO_HEADER}${pathParamsOut}`,
  'utf8',
);

writeFileSync(
  join(pathsDir, 'get-path.ts'),
  `${AUTO_HEADER}/**
 * Получить URL для эндпоинта с параметрами.
 */
export function getPath(
  pathFn: ((params: Record<string, string | number>) => string) | string,
  params?: Record<string, string | number>,
): string {
  if (typeof pathFn === 'function') {
    return pathFn(params || {});
  }
  return pathFn;
}
`,
  'utf8',
);

let pathsIndex = AUTO_HEADER;
pathsIndex += `export type { PathParams } from './path-params';\n`;
pathsIndex += `export { getPath } from './get-path';\n\n`;

for (const { moduleName, exportName } of pathModuleNames) {
  pathsIndex += `import { ${exportName} } from './${moduleName}.paths';\n`;
}

pathsIndex += `\nexport const apiPaths = {\n`;
for (const { tag, moduleName, exportName } of pathModuleNames) {
  pathsIndex += `  /** ${tag} */\n`;
  pathsIndex += `  ${moduleName}: ${exportName},\n`;
}
pathsIndex += `} as const;\n\nexport type ApiPaths = typeof apiPaths;\n`;

writeFileSync(join(pathsDir, 'index.ts'), pathsIndex, 'utf8');

// --- unwraps per tag ---
const unwrapModuleNames = [];

for (const [tag, ops] of Object.entries(unwrappersByTag).sort(([a], [b]) =>
  a.localeCompare(b),
)) {
  const moduleName = cleanTag(tag);
  const exportName = `${moduleName}Unwrappers`;
  unwrapModuleNames.push({ tag, moduleName, exportName });

  let file = AUTO_HEADER;
  file += `import { throwIfApiError } from '../../src/error/error.handler';\n\n`;
  file += `/** ${tag} unwrappers */\n`;
  file += `export const ${exportName} = {\n`;

  for (const [opId, unwrapper] of Object.entries(ops)) {
    const item = grouped[tag]?.find((i) => i.opId === opId);
    if (item?.summary) {
      file += `  /** ${item.summary} */\n`;
    }
    file += `${unwrapper}\n`;
  }

  file += `} as const;\n`;
  writeFileSync(join(unwrapsDir, `${moduleName}.unwrap.ts`), file, 'utf8');
}

let unwrapsIndex = AUTO_HEADER;
for (const { moduleName, exportName } of unwrapModuleNames) {
  unwrapsIndex += `import { ${exportName} } from './${moduleName}.unwrap';\n`;
}

unwrapsIndex += `\nexport const unwrappers = {\n`;
for (const { tag, moduleName, exportName } of unwrapModuleNames) {
  unwrapsIndex += `  /** ${tag} */\n`;
  unwrapsIndex += `  ${moduleName}: ${exportName},\n`;
}
unwrapsIndex += `} as const;\n\nexport type Unwrappers = typeof unwrappers;\n\n`;
unwrapsIndex += `export function unwrap<T>(
  response: unknown,
  unwrapper: (response: unknown) => T,
): T {
  return unwrapper(response);
}\n`;

writeFileSync(join(unwrapsDir, 'index.ts'), unwrapsIndex, 'utf8');

const totalEndpoints = Object.values(grouped).reduce(
  (acc, items) => acc + items.length,
  0,
);
console.log(`✅ paths: ${pathsDir} (${pathModuleNames.length} файлов)`);
console.log(`✅ unwraps: ${unwrapsDir} (${unwrapModuleNames.length} файлов)`);
console.log(`📊 ${totalEndpoints} эндпоинтов в ${tagEntries.length} тегах`);
